export class TaskQueue<T> {
  private tasks: T[] = [];

  enqueue(task: T): number {
    this.tasks.push(task);
    return this.tasks.length;
  }

  dequeue(): T | undefined {
    return this.tasks.shift();
  }

  peek(): T | undefined {
    return this.tasks[0];
  }

  size(): number {
    return this.tasks.length;
  }
}
